System:
  OS: Windows 11 10.0.26200
  CPU: (12) x64 12th Gen Intel(R) Core(TM) i5-1235U
  Memory: 15.68 GB
Binaries:
  Node: 22.14.0
  npm: 10.9.2
npmPackages:
  @playwright/test: 1.64.1
```

